{
  "name": "wsl-notify",
  "version": "1.0.6",
  "description": "Windows toast notifications for OpenCode — permission, question, session completion and error events. Zero dependencies, one entrypoint for OpenCode V1 and V2, works from WSL (powershell.exe interop) and native Windows.",
  "type": "module",
  "exports": {
    ".": "./index.js",
    "./server": "./index.js"
  },
  "main": "index.js",
  "files": [
    "index.js",
    "README.md",
    "LICENSE"
  ],
  "keywords": [
    "opencode",
    "opencode-plugin",
    "notification",
    "notifications",
    "toast",
    "windows",
    "wsl",
    "powershell"
  ],
  "license": "MIT",
  "author": "Alexey Shirshov",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/AlexeyShirshov/skills.git",
    "directory": "opencode/plugins/wsl-notify"
  },
  "engines": {
    "node": ">=18"
  },
  "scripts": {
    "test": "node test/smoke.mjs"
  }
}

// Windows toast notifications for OpenCode (V1 and V2).
//
// One entrypoint serves both generations: V2 reads `id`/`setup()` and delivers
// events through `ctx.event.subscribe()`; V1 calls `server()` and uses the
// returned hooks. V2 replaced the V1 `question.asked` event with `form.created`,
// so both shapes are handled.
//
// V2 also loads the same plugin once per location activation: several instances
// per server process, each with its own module graph, all subscribed to the same
// event stream. Shared state therefore lives on `globalThis`, so one request
// produces exactly one toast (V1 sent one as well).
//
// There is no Bun `$` helper in V2 and no dependency is needed: the plugin is a
// plain object, so it works in both generations without `@opencode/plugin`.

import { spawn } from "node:child_process"
import { existsSync, readFileSync } from "node:fs"
import { appendFile } from "node:fs/promises"
import { randomUUID } from "node:crypto"
import { delimiter, join } from "node:path"
import { tmpdir } from "node:os"

const APP_ID = "{1AC14E77-02E7-4E5D-B744-2EB1AE5198B7}\\WindowsPowerShell\\v1.0\\powershell.exe"

const DEFAULTS = {
  maxTitle: 60,
  maxMessage: 240,
  // A permission that is answered inside this window never reaches the desktop.
  // See the README: with `session.permissions: "autoaccept"` the TUI answers at
  // once, and only the events would tell you otherwise.
  graceMs: 500,
  // A turn that starts and finishes inside this window was answered while you
  // were still looking at the terminal, so it never reaches the desktop either.
  // `0` notifies for every finished turn.
  minTurnMs: 500,
  // Subagent completions are noise by default: the parent session reports the
  // turn that spawned them.
  subagentComplete: false,
  // Sessions whose titles contain one of these literal substrings keep their
  // finished and failed turns off the desktop. `WSL_NOTIFY_EXCLUDE_SESSION_TITLES`
  // carries the same list as a JSON array.
  excludeSessionTitles: [],
  sound: {
    permission: "Notification.IM",
    question: "Notification.Default",
    complete: "Notification.Default",
    error: "Notification.Reminder",
  },
}

// Windows installations on a DrvFs/9p mount, and PowerShell 7 next to it.
const POWERSHELL_RELATIVE = [
  "Windows/System32/WindowsPowerShell/v1.0/powershell.exe",
  "WINDOWS/System32/WindowsPowerShell/v1.0/powershell.exe",
  "Program Files/PowerShell/7/pwsh.exe",
]

const POWERSHELL_NAMES = ["powershell.exe", "pwsh.exe", "powershell", "pwsh"]

const COMPLETE_EVENTS = new Set(["session.execution.succeeded", "session.idle"])
// `session.execution.*` is V2; 1.18.x reports a failed turn as `session.error`,
// with the text in `properties.error.data.message`.
const ERROR_EVENTS = new Set(["session.execution.failed", "session.error"])
const SESSION_START_EVENTS = new Set(["session.execution.started"])

// When does a new turn begin? V2 says so with `session.execution.started`; 1.18.x
// never emits that, so there a turn begins with a user message — but only with a
// *new* one: 1.18.x re-emits the same message later with its summary, and treating
// that re-emission as a new turn would both release the completion key and reset
// the short-turn mark right before the turn ends (observed live: held=2ms, so
// `minTurnMs` swallowed the toast). Without any turn boundary the completion key
// is never released and a long-lived process (the TUI keeps one server for the
// whole session) would toast only the very first finished turn.
function turnStart(event) {
  const type = event?.type
  if (SESSION_START_EVENTS.has(type)) return true
  if (type !== "message.updated") return false

  const info = event.data?.info ?? event.properties?.info ?? event.data ?? event.properties
  if (info?.role !== "user") return false

  const sessionID = sessionIDOf(event)
  const id = info.id ?? event.data?.messageID ?? event.properties?.messageID
  if (!sessionID || id === undefined) return true
  if (state.userMessage.get(sessionID) === id) return false
  state.userMessage.set(sessionID, id)
  if (state.userMessage.size > MAX_SEEN) {
    for (const oldest of state.userMessage.keys()) {
      state.userMessage.delete(oldest)
      if (state.userMessage.size <= MAX_SEEN - 64) break
    }
  }
  return true
}

// Diagnostics: `WSL_NOTIFY_DEBUG=1` in the environment of the opencode process
// writes every decision (toast/skip) to WSL_NOTIFY_DEBUG_LOG
// (default `$TMPDIR/wsl-notify.log`).
const INSTANCE = randomUUID().slice(0, 8)
const DEBUG_LOG = process.env.WSL_NOTIFY_DEBUG_LOG ?? join(tmpdir(), "wsl-notify.log")

function debug(line) {
  if (process.env.WSL_NOTIFY_DEBUG !== "1") return
  void appendFile(DEBUG_LOG, `${new Date().toISOString()} ${INSTANCE} ${line}\n`).catch(() => {})
}

// One line per process as soon as the plugin is actually registered, written
// whether or not debugging is on. It is the only way to tell "the plugin never
// loaded" (no line at all) apart from "it loaded and stayed quiet", which is
// otherwise indistinguishable from the outside — the question that came up when a
// toast went missing on a host where the plugin had simply not been refreshed.
function noteLoaded(where) {
  if (state.loadedAt) return
  state.loadedAt = new Date().toISOString()
  let powershell = ""
  try {
    powershell = resolvePowerShell() ?? "none"
  } catch {
    powershell = "error"
  }
  void appendFile(
    DEBUG_LOG,
    `${state.loadedAt} ${INSTANCE} loaded path=${where} powershell=${powershell}\n`,
  ).catch(() => {})
}

// Dedupe: one toast per request. The key is the request id (form/permission) or
// the session plus turn (completion), never the event id, because V2 delivers one
// event to several plugin instances, re-emits `permission.asked` for a pending
// request, and can report one finished turn as both `session.execution.succeeded`
// and the legacy `session.idle`. `started` carries the turn start time for the
// `minTurnMs` window, and `pending` the grace timers.
const STATE_KEY = Symbol.for("opencode.wsl-notify.state")
const state = (globalThis[STATE_KEY] ??= {
  seen: new Set(),
  pending: new Map(),
  started: new Map(),
  sessions: new Map(),
  priming: new Set(),
  userMessage: new Map(),
  loadedAt: undefined,
  warned: new Set(),
  resolved: false,
  powershell: undefined,
})
const MAX_SEEN = 512

function warnOnce(key, message) {
  if (state.warned.has(key)) return
  state.warned.add(key)
  console.error(message)
}

function findOnPath(name) {
  const dirs = (process.env.PATH ?? "").split(delimiter).filter(Boolean)
  const names = process.platform === "win32" ? [name] : [`${name}.exe`, name]
  for (const dir of dirs) {
    for (const candidate of names) {
      const full = join(dir, candidate)
      if (existsSync(full)) return full
    }
  }

  return undefined
}

function windowsMounts() {
  const mounts = []
  try {
    for (const line of readFileSync("/proc/mounts", "utf8").split("\n")) {
      const [mount, , type] = line.split(/\s+/)
      if (!mount || !/^\/mnt\/[a-z]$/i.test(mount)) continue
      if (type === "drvfs" || type === "9p" || type === "cifs") mounts.push(mount)
    }
  } catch {
    // Not Linux: no DrvFs mounts to scan.
  }

  if (mounts.length === 0 && existsSync("/mnt/c")) mounts.push("/mnt/c")
  return mounts
}

// Resolution order: explicit option, `WSL_NOTIFY_POWERSHELL`, PATH (native
// Windows and WSL interop put powershell.exe there), then the Windows drive
// mounts of a WSL host.
export function resolvePowerShell(options) {
  const explicit = options?.powershell ?? process.env.WSL_NOTIFY_POWERSHELL
  if (typeof explicit === "string" && explicit.length > 0) {
    if (existsSync(explicit)) return explicit
    const onPath = findOnPath(explicit)
    if (onPath) return onPath
    warnOnce("explicit", `[wsl-notify] powershell not found at "${explicit}", falling back to discovery`)
  }

  for (const name of POWERSHELL_NAMES) {
    const found = findOnPath(name)
    if (found) return found
  }

  for (const mount of windowsMounts()) {
    for (const relative of POWERSHELL_RELATIVE) {
      const full = join(mount, relative)
      if (existsSync(full)) return full
    }
  }

  return undefined
}

function powershell(options) {
  if (state.resolved && state.powershell) return state.powershell

  if (!state.resolved) {
    state.powershell = resolvePowerShell(options)
    state.resolved = true
  }

  if (!state.powershell) {
    warnOnce(
      "missing",
      "[wsl-notify] powershell.exe not found (set WSL_NOTIFY_POWERSHELL or the plugin's `powershell` option); notifications are skipped",
    )
  }

  return state.powershell
}

function sessionIDOf(event) {
  // V2 puts the session id on the event itself; 1.18.x nests the session for
  // `session.created`/`session.updated` under `properties.info`.
  return event?.data?.sessionID ?? event?.properties?.sessionID ?? event?.properties?.info?.id
}

// Classify the event and build its dedupe key. `undefined` means "not ours".
function classify(event) {
  switch (event?.type) {
    case "permission.asked": {
      const id = event.data?.id ?? event.data?.requestID ?? event.properties?.id ?? event.properties?.requestID
      const key = id === undefined || id === null ? (event.id ? `event:${event.id}` : undefined) : `permission:${id}`
      return { kind: "permission", key, sessionID: sessionIDOf(event) }
    }

    case "form.created": {
      const id = event.data?.form?.id
      const key = id === undefined || id === null ? (event.id ? `event:${event.id}` : undefined) : `form:${id}`
      return { kind: "question", key, sessionID: sessionIDOf(event) }
    }

    case "question.asked": {
      const first = event.properties?.questions?.[0]
      const key =
        first?.question === undefined
          ? event.id && `event:${event.id}`
          : `question:${sessionIDOf(event) ?? ""}:${first.question}`
      return { kind: "question", key, sessionID: sessionIDOf(event) }
    }

    default: {
      const sessionID = sessionIDOf(event)
      if (COMPLETE_EVENTS.has(event?.type)) return { kind: "complete", key: `done:${sessionID}`, sessionID }
      if (ERROR_EVENTS.has(event?.type)) return { kind: "error", key: `failed:${sessionID}`, sessionID }
      return undefined
    }
  }
}

function cancelPending(key) {
  const timer = state.pending.get(key)
  if (timer === undefined) return
  clearTimeout(timer)
  state.pending.delete(key)
}

function forgetKey(key) {
  if (!key) return
  // A pending toast that never fires is worth a line: without it a permission
  // answered inside the grace window looks exactly like a plugin that never saw
  // the event.
  if (state.pending.has(key)) debug(`skip ${key} answered inside the grace window`)
  cancelPending(key)
  state.seen.delete(key)
}

function forget(event) {
  // A replied or cancelled request is no longer pending: drop its key so the
  // grace timer stops and nothing is toasted.
  if (event?.type === "permission.replied") {
    const id = event.data?.requestID ?? event.data?.id ?? event.properties?.requestID ?? event.properties?.id
    forgetKey(id === undefined || id === null ? undefined : `permission:${id}`)
  }

  if (event?.type === "form.replied" || event?.type === "form.cancelled") {
    const id = event.data?.id ?? event.data?.form?.id
    forgetKey(id === undefined || id === null ? undefined : `form:${id}`)
  }

  // A new turn begins: release the completion key so the next completion can
  // toast, and remember when the turn began for the `minTurnMs` window. The mark
  // is never reset while a turn is running, so a late event cannot shorten it.
  if (turnStart(event)) {
    const sessionID = sessionIDOf(event)
    forgetKey(`done:${sessionID}`)
    forgetKey(`failed:${sessionID}`)
    if (sessionID && !state.started.has(sessionID)) {
      state.started.set(sessionID, Date.now())
      if (state.started.size > MAX_SEEN) {
        for (const oldest of state.started.keys()) {
          state.started.delete(oldest)
          if (state.started.size <= MAX_SEEN - 64) break
        }
      }
    }
  }
}

function firstTime(key) {
  if (!key) return true
  if (state.seen.has(key)) return false

  state.seen.add(key)
  if (state.seen.size > MAX_SEEN) {
    for (const oldest of state.seen) {
      state.seen.delete(oldest)
      if (state.seen.size <= MAX_SEEN - 64) break
    }
  }

  return true
}

const psQuote = (value) => `'${String(value).replace(/'/g, "''")}'`

const xmlEscape = (value) =>
  String(value)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;")

function buildScript(title, message, sound) {
  const xml =
    '<toast><visual><binding template="ToastGeneric">' +
    `<text>${xmlEscape(title)}</text>` +
    `<text>${xmlEscape(message)}</text>` +
    "</binding></visual>" +
    `<audio src="ms-winsoundevent:${sound}"/>` +
    "</toast>"
  return [
    "$ErrorActionPreference='Stop'",
    "[Windows.UI.Notifications.ToastNotificationManager, Windows.UI.Notifications, ContentType=WindowsRuntime] | Out-Null",
    "[Windows.Data.Xml.Dom.XmlDocument, Windows.Data.Xml.Dom.XmlDocument, ContentType=WindowsRuntime] | Out-Null",
    "$xml = New-Object Windows.Data.Xml.Dom.XmlDocument",
    `$xml.LoadXml(${psQuote(xml)})`,
    "$toast = New-Object Windows.UI.Notifications.ToastNotification $xml",
    `[Windows.UI.Notifications.ToastNotificationManager]::CreateToastNotifier(${psQuote(APP_ID)}).Show($toast)`,
  ].join("; ")
}

// V2 describes the request as a form, V1 as a list of questions. Normalize both.
function formOf(event) {
  if (event?.type === "form.created") return event.data?.form

  if (event?.type === "question.asked") {
    const questions = Array.isArray(event.properties?.questions) ? event.properties.questions : []
    return {
      title: questions[0]?.header,
      fields: questions.map((question) => ({ title: question?.question })),
    }
  }

  return undefined
}

function numberFromEnv(name) {
  const raw = process.env[name]
  if (raw === undefined || raw === "") return undefined
  const value = Number(raw)
  return Number.isFinite(value) ? value : undefined
}

// `WSL_NOTIFY_EXCLUDE_SESSION_TITLES` holds a JSON array: a comma-separated list
// cannot represent a title that contains a comma. A malformed value fails open —
// no filter — rather than silencing notifications.
function listFromEnv(name) {
  const raw = process.env[name]
  if (raw === undefined || raw === "") return undefined
  try {
    return JSON.parse(raw)
  } catch {
    return undefined
  }
}

// The option wins over the environment, and `[]` is a deliberate "no filter", so
// it overrides the environment too; so does an invalid non-null option. Only
// non-empty strings take part in matching, literally: case and whitespace are
// significant and no pattern is interpreted.
function excludedTitles(options) {
  const configured = options?.excludeSessionTitles ?? listFromEnv("WSL_NOTIFY_EXCLUDE_SESSION_TITLES")
  if (!Array.isArray(configured)) return []
  return configured.filter((entry) => typeof entry === "string" && entry.length > 0)
}

function limits(options) {
  // Option wins, then the environment: a locally discovered plugin file has no
  // options, so the environment is the only knob there.
  const grace = options?.graceMs ?? numberFromEnv("WSL_NOTIFY_GRACE_MS")
  const minTurn = options?.minTurnMs ?? numberFromEnv("WSL_NOTIFY_MIN_TURN_MS")

  return {
    maxTitle: Number.isFinite(options?.maxTitle) ? options.maxTitle : DEFAULTS.maxTitle,
    maxMessage: Number.isFinite(options?.maxMessage) ? options.maxMessage : DEFAULTS.maxMessage,
    graceMs: Number.isFinite(grace) ? Math.max(0, grace) : DEFAULTS.graceMs,
    minTurnMs: Number.isFinite(minTurn) ? Math.max(0, minTurn) : DEFAULTS.minTurnMs,
    subagentComplete: options?.subagentComplete === true,
    excludeSessionTitles: excludedTitles(options),
    sound: { ...DEFAULTS.sound, ...(options?.sound ?? {}) },
  }
}

function render(classified, event, sessionID, options) {
  const { maxTitle, maxMessage, graceMs, subagentComplete, sound } = limits(options)
  const title = String(sessionTitle(sessionID) ?? "opencode").slice(0, maxTitle)

  switch (classified.kind) {
    case "permission":
      return { title: "opencode", message: "Permission needs input", sound: sound.permission, delayMs: graceMs }

    case "question": {
      const form = formOf(event)
      if (!form) return undefined
      const fields = Array.isArray(form.fields) ? form.fields : []
      const first = fields[0] ?? {}
      const candidate = first.title || first.description || form.title || "Question needs input"
      let message = String(candidate)
      if (fields.length > 1) message += ` (+${fields.length - 1})`
      return {
        title: String(form.title || "opencode").slice(0, maxTitle),
        message: message.slice(0, maxMessage),
        sound: sound.question,
      }
    }

    case "complete":
      return {
        title,
        message: isSubagent(sessionID) && subagentComplete ? "Subagent finished" : "Session finished",
        sound: sound.complete,
      }

    case "error": {
      const detail =
        event.data?.error?.message ??
        event.properties?.error?.message ??
        event.properties?.error?.data?.message
      return {
        title,
        message: (detail ? `Error: ${detail}` : "Session failed").slice(0, maxMessage),
        sound: sound.error,
      }
    }

    default:
      return undefined
  }
}

// Remember what the event stream says about a session. The plugin never calls
// into the server from the event handler: a session read issued while that same
// session is finishing does not come back (observed live — the handler stops at
// the call and no fallback timer fires), which is exactly the moment a
// completion toast is raised. `session.created` carries `parentID` for a subagent
// session and omits it for a top-level one, so the stream alone is enough.
function track(event) {
  const type = event?.type
  if (typeof type !== "string" || !type.startsWith("session.")) return

  const sessionID = sessionIDOf(event)
  if (!sessionID) return

  if (type === "session.deleted") {
    state.sessions.delete(sessionID)
    state.userMessage.delete(sessionID)
    return
  }

  if (type !== "session.created" && type !== "session.updated" && type !== "session.renamed") return

  // 1.18.x nests the session under `properties.info`; V2 puts the fields on the
  // event itself.
  const info = event.properties?.info
  const parentID = event.data?.parentID ?? event.properties?.parentID ?? info?.parentID
  const title = event.data?.title ?? event.properties?.title ?? info?.title
  rememberSession(sessionID, { parentID, title })
}

function isSubagent(sessionID) {
  const parentID = state.sessions.get(sessionID)?.parentID
  return typeof parentID === "string" && parentID.length > 0
}

function sessionTitle(sessionID) {
  const title = state.sessions.get(sessionID)?.title
  return typeof title === "string" && title.length > 0 ? title : undefined
}

function rememberSession(sessionID, session) {
  const meta = state.sessions.get(sessionID) ?? {}
  if (session.title !== undefined) meta.title = session.title
  if (session.parentID !== undefined) meta.parentID = session.parentID
  state.sessions.set(sessionID, meta)

  if (state.sessions.size > MAX_SEEN) {
    for (const oldest of state.sessions.keys()) {
      state.sessions.delete(oldest)
      if (state.sessions.size <= MAX_SEEN - 64) break
    }
  }
}

// Ask the server for a session we have never seen, so that a session created
// before the plugin loaded (or before a reload) still gets its title and its
// `parentID`. This is deliberately *not* awaited: a read issued while that
// session is finishing never comes back, and the event handler must not stop on
// it. Started when the session first appears, it has the whole turn to answer.
const PRIME_RETRY_MS = 30_000

function primeSession(ctx, sessionID) {
  if (typeof ctx?.session?.get !== "function") return
  if (state.priming.has(sessionID)) return
  state.priming.add(sessionID)

  const timer = setTimeout(() => state.priming.delete(sessionID), PRIME_RETRY_MS)
  timer.unref?.()

  void Promise.resolve()
    .then(() => ctx.session.get({ sessionID }))
    .then((session) => {
      if (!session) return
      rememberSession(sessionID, session)
      debug(`primed ${sessionID} title=${JSON.stringify(session.title)} parent=${JSON.stringify(session.parentID)}`)
    })
    .catch((error) => debug(`prime failed ${sessionID}: ${error?.message ?? error}`))
    .finally(() => {
      clearTimeout(timer)
      state.priming.delete(sessionID)
    })
}

function primeUnknown(event, prime) {
  if (!prime) return
  const sessionID = sessionIDOf(event)
  if (!sessionID) return
  // A title is the cheapest sign of a complete record; without one, ask.
  if (state.sessions.get(sessionID)?.title !== undefined) return
  prime(sessionID)
}

function toast(info, options) {
  const executable = powershell(options)
  if (!executable) return

  // The script travels through `-Command`, not `-EncodedCommand`: base64 of the
  // UTF-16LE text inflates the single argument ~2.7x, and a host whose interop
  // layer caps an argument at ~2 KB kills the spawn with EINVAL (`powershell.exe:
  // Invalid argument`, exit 1) — invisibly, because stdio is ignored. Spawned
  // without a shell the script is one argv element, so the single quoting
  // `buildScript` applies is all it needs; `-ExecutionPolicy` is unnecessary
  // because the script never comes from a file.
  const child = spawn(
    executable,
    [
      "-NoProfile",
      "-NonInteractive",
      "-WindowStyle",
      "Hidden",
      "-Command",
      buildScript(info.title, info.message, info.sound),
    ],
    // Hide the console at launch; PowerShell's own flag can act only after startup.
    { stdio: "ignore", windowsHide: true },
  )
  child.on("error", (error) => console.error(`[wsl-notify] "${executable}" failed: ${error.message}`))
}

// Both timing knobs come from the same options as everywhere else. A 1.18.x host
// that supplies no options — a bare specifier or local auto-discovery — keeps the
// defaults, and `WSL_NOTIFY_*` is the override.
function schedule(key, info, options) {
  const delayMs = Number.isFinite(info.delayMs) ? info.delayMs : 0
  if (delayMs <= 0) {
    debug(`toast ${key}`)
    toast(info, options)
    return
  }

  const timer = setTimeout(() => {
    state.pending.delete(key)
    debug(`toast-delayed ${key} after=${delayMs}ms`)
    toast(info, options)
  }, delayMs)
  timer.unref?.()
  state.pending.set(key, timer)
  debug(`delayed ${key} after=${delayMs}ms`)
}

async function handle(event, options, prime) {
  track(event)
  forget(event)
  primeUnknown(event, prime)

  const classified = classify(event)
  if (!classified) return

  // Subagent completions are noise. Only completions are filtered: a failing
  // agent is worth a toast even when it is a child session.
  if (classified.kind === "complete" && isSubagent(classified.sessionID) && !limits(options).subagentComplete) {
    debug(`skip-subagent ${event?.type} session=${classified.sessionID}`)
    return
  }

  // A session whose title matches the filter keeps its finished and failed turns
  // off the desktop. Only the real cached title counts: the `"opencode"` display
  // fallback, the session id and the error text would filter far too much.
  if (classified.kind === "complete" || classified.kind === "error") {
    const title = sessionTitle(classified.sessionID)
    const match =
      title === undefined
        ? undefined
        : limits(options).excludeSessionTitles.find((entry) => title.includes(entry))
    if (match !== undefined) {
      debug(`skip-excluded ${classified.kind} session=${classified.sessionID} match=${JSON.stringify(match)}`)
      return
    }
  }

  // How long the turn ran. `undefined` when no start event was seen (the plugin
  // loaded mid-turn, the event was missed, or the service restarted): fail open
  // and notify, because a missing mark says nothing about the turn.
  let heldMs
  if (classified.kind === "complete") {
    const startedAt = state.started.get(classified.sessionID)
    state.started.delete(classified.sessionID)
    if (startedAt !== undefined) heldMs = Date.now() - startedAt
  }

  const info = render(classified, event, classified.sessionID, options)
  if (!info) return

  // Claim first: `session.execution.succeeded` and the legacy `session.idle`
  // report the same turn, and the second one must not slip past the window.
  if (!firstTime(classified.key)) {
    debug(`skip ${classified.kind} key=${classified.key} event.id=${event?.id}`)
    return
  }

  const { minTurnMs } = limits(options)
  if (heldMs !== undefined && heldMs < minTurnMs) {
    debug(`skip-short ${classified.kind} session=${classified.sessionID} held=${heldMs}ms min=${minTurnMs}ms`)
    return
  }

  schedule(classified.key, info, options)
}

export default {
  id: "wsl-notify",

  // V2: events arrive through the server event stream.
  setup(ctx) {
    const options = ctx?.options ?? {}

    // 1.18.x calls `setup` too, but its context carries no event stream (keys:
    // options, agent, aisdk, catalog, command, integration, plugin, reference,
    // skill — no `event`, `client` or `$`). There is nothing to subscribe to, so
    // leave quietly: the `server()` hooks are the only event path on that
    // generation.
    if (typeof ctx?.event?.subscribe !== "function") {
      debug("setup: no event stream in this context (1.18.x); the server() hooks serve events")
      return
    }

    const controller = new AbortController()
    const prime = (sessionID) => primeSession(ctx, sessionID)
    noteLoaded("v2")

    void (async () => {
      try {
        for await (const event of ctx.event.subscribe({ signal: controller.signal })) {
          try {
            await handle(event, options, prime)
          } catch (error) {
            console.error(`[wsl-notify] handler failed: ${error?.message ?? error}`)
          }
        }
      } catch (error) {
        if (!controller.signal.aborted) {
          console.error(`[wsl-notify] event stream ended: ${error?.message ?? error}`)
        }
      }
    })()

    return () => controller.abort()
  },

  // V1: the server calls this and uses the returned hooks. V1 loads the plugin
  // once per process, and its `session.idle` is the completion event. Options
  // arrive as the second argument when the config names them in the tuple form;
  // a bare specifier or local auto-discovery supplies none, and `WSL_NOTIFY_*`
  // is the override there.
  async server(input, options = {}) {
    const resolved = options ?? {}
    noteLoaded("v1")
    return {
      event: async ({ event }) => {
        try {
          await handle(event, resolved)
        } catch (error) {
          console.error(`[wsl-notify] handler failed: ${error?.message ?? error}`)
        }
      },
    }
  },
}
